 *
 * @param payload — Checkout payload from cart store
 * @returns Sale response with sale header, payment, and line items
 */
export async function submitCheckout(payload: CheckoutPayload): Promise<SaleResponse> {
  const response = await fetch(`${API_BASE}/api/sales`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  })

  if (!response.ok) {
    const errorBody = (await response.json().catch(() => ({}))) as SaleError
    throw new Error(errorBody.error ?? `Checkout failed with status ${response.status}`)
  }

  return (await response.json()) as SaleResponse
}

/**
 * Extract sale number and total from a successful checkout response.
 */
export function parseCheckoutSuccess(response: SaleResponse): CheckoutSuccess {
  const sale = response.sale as Record<string, unknown>
  return {
    saleNumber: String(sale.sale_number ?? ''),
    totalGross: Number(sale.total_gross ?? 0),
  }
}

