// ── Mixed Cart (part + labor + bicycle) ────────────────────────────

describe('Cart Store — mixed cart operations', () => {
  beforeEach(() => createFreshStore())

  it('supports adding all three line item types to the same cart', () => {
    useCartStore.getState().addLineItem(mockPart, 2)
    useCartStore.getState().addLaborLineItem({
      description: 'Assembly',
      minutesWorked: 45,
      hourlyRateSnapshot: 60000,
    })
    useCartStore.getState().addBicycleLineItem({
      description: 'New bike',
      priceNet: 120000,
      bicycleBrand: 'Canyon',
      bicycleModel: 'Ultimate CF SL',
    })

    const state = useCartStore.getState()
    expect(state.lineItems).toHaveLength(3)
    expect(state.lineItems[0].lineType).toBe('part')
    expect(state.lineItems[1].lineType).toBe('labor')
    expect(state.lineItems[2].lineType).toBe('bicycle')
  })

  it('aggregates totals correctly across mixed line item types', () => {
    // Part: priceNet=500, qty=2 → net=1000, vat(21%)=210, gross=1210
    useCartStore.getState().addLineItem(mockPart, 2)
    // Labor: 30min at €60/hr = (30/60)*60000 = 30000 → net=30000, vat(21%)=6300, gross=36300
    useCartStore.getState().addLaborLineItem({
      description: 'Assembly',
      minutesWorked: 30,
      hourlyRateSnapshot: 60000,
    })
    // Bicycle: priceNet=120000, qty=1 → net=120000, vat(21%)=25200, gross=145200
    useCartStore.getState().addBicycleLineItem({
      description: 'New bike',
      priceNet: 120000,
      bicycleBrand: 'Canyon',
      bicycleModel: 'Ultimate CF SL',
    })

    const state = useCartStore.getState()
    // subtotalNet = 1000 + 30000 + 120000 = 151000
    expect(state.subtotalNet).toBe(151000)
    // vatTotal = 210 + 6300 + 25200 = 31710
    expect(state.vatTotal).toBe(31710)
    // totalGross = 151000 + 31710 = 182710
    expect(state.totalGross).toBe(182710)
  })

  it('removes specific line item by id without affecting others', () => {
    useCartStore.getState().addLineItem(mockPart, 1)
    const laborInput = { description: 'Assembly', minutesWorked: 30, hourlyRateSnapshot: 60000 }
    useCartStore.getState().addLaborLineItem(laborInput)
    useCartStore.getState().addBicycleLineItem({
      description: 'New bike',
      priceNet: 120000,
      bicycleBrand: 'Canyon',
      bicycleModel: 'Ultimate CF SL',
    })

    const laborId = useCartStore.getState().lineItems[1].id
    useCartStore.getState().removeLineItem(laborId)

    const state = useCartStore.getState()
    expect(state.lineItems).toHaveLength(2)
    expect(state.lineItems[0].lineType).toBe('part')
    expect(state.lineItems[1].lineType).toBe('bicycle')
  })
})

// ── Checkout Payload (discriminated union) ─────────────────────────

describe('Cart Store — checkout payload with discriminated union', () => {
  beforeEach(() => createFreshStore())

  it('maps part line items to correct checkout shape', () => {
    useCartStore.getState().addLineItem(mockPart, 2)

    const payload = useCartStore.getState().getCheckoutPayload()

    expect(payload.lineItems).toHaveLength(1)
    const lineItem = payload.lineItems[0]
    expect(lineItem.lineType).toBe('part')
    expect(lineItem.partId).toBe(mockPart.id)
    expect(lineItem.quantity).toBe(2)
    expect(lineItem.unitPriceNet).toBe(mockPart.priceNet)
    expect(lineItem.description).toBe(mockPart.name)
  })

  it('maps labor line items to correct checkout shape', () => {
    useCartStore.getState().addLaborLineItem({
      description: 'Brake adjustment',
      minutesWorked: 30,
      hourlyRateSnapshot: 60000,
      laborServiceId: 'svc-brakes',
    })

    const payload = useCartStore.getState().getCheckoutPayload()

    expect(payload.lineItems).toHaveLength(1)
    const lineItem = payload.lineItems[0]
    expect(lineItem.lineType).toBe('labor')
    expect(lineItem.description).toBe('Brake adjustment')
    expect(lineItem.minutesWorked).toBe(30)
    expect(lineItem.hourlyRateSnapshot).toBe(60000)
    expect(lineItem.laborServiceId).toBe('svc-brakes')
  })

  it('maps bicycle line items to correct checkout shape', () => {
    useCartStore.getState().addBicycleLineItem({
      description: 'Road bike sale',
      priceNet: 120000,
      bicycleBrand: 'Specialized',
      bicycleModel: 'Tarmac SL7',
      bicycleYear: 2024,
      bicycleColor: 'Red',
      bicycleFrameSize: '56cm',
    })

    const payload = useCartStore.getState().getCheckoutPayload()

    expect(payload.lineItems).toHaveLength(1)
    const lineItem = payload.lineItems[0]
    expect(lineItem.lineType).toBe('bicycle')
    expect(lineItem.description).toBe('Road bike sale')
    expect(lineItem.bicycleBrand).toBe('Specialized')
    expect(lineItem.bicycleModel).toBe('Tarmac SL7')
    expect(lineItem.bicycleYear).toBe(2024)
    expect(lineItem.bicycleColor).toBe('Red')
    expect(lineItem.bicycleFrameSize).toBe('56cm')
  })

  it('maps mixed cart to correct checkout payload with all types', () => {
    useCartStore.getState().addLineItem(mockPart, 1)
    useCartStore.getState().addLaborLineItem({
      description: 'Assembly',
      minutesWorked: 45,
      hourlyRateSnapshot: 60000,
    })
    useCartStore.getState().addBicycleLineItem({
      description: 'New bike',
      priceNet: 120000,
      bicycleBrand: 'Canyon',
      bicycleModel: 'Ultimate CF SL',
    })

    const payload = useCartStore.getState().getCheckoutPayload()

    expect(payload.lineItems).toHaveLength(3)
    expect(payload.lineItems[0].lineType).toBe('part')
    expect((payload.lineItems[0] as any).partId).toBe(mockPart.id)
    expect(payload.lineItems[1].lineType).toBe('labor')
    expect((payload.lineItems[1] as any).minutesWorked).toBe(45)
    expect(payload.lineItems[2].lineType).toBe('bicycle')
    expect((payload.lineItems[2] as any).bicycleBrand).toBe('Canyon')
  })
})

