import { create } from 'zustand'

// ============================================================================
// Types
// ============================================================================

/** A part from the catalog, ready to be added to cart */
export interface PartCatalogItem {
  id: string
  barcode: string
  name: string
  priceNet: number // in cents (integer)
  quantityOnHand: number
}

/** VAT rate ID constants — matches server vatRates table */
export const VAT_RATES = {
  'vat-standard': 2100, // 21%
  'vat-reduced': 600,   // 6%
  'vat-zero': 0,        // 0%
} as const

/** Default VAT rate for parts */
export const DEFAULT_VAT_RATE = 'vat-standard' as const

// ---------------------------------------------------------------------------
// Cart Line Item — Discriminated Union (part | labor | bicycle)
// ---------------------------------------------------------------------------

/** Shared fields for all cart line item types */
interface BaseCartLineItem {
  /** Unique identifier for this line item in the cart */
  id: string
  /** Human-readable description of the line item */
  description: string
  /** Unit price net (ex-tax cents per unit, snapshot at add time) */
  priceNet: number
  /** Quantity of units */
  quantity: number
  /** VAT rate ID for this line item */
  vatRateId: keyof typeof VAT_RATES
  /** Discount in basis points, e.g. 1000 = 10% — null means no discount */
  discountPercent: number | null
  // Computed totals (updated whenever qty/discount changes)
  lineTotalNet: number
  lineTotalVat: number
  lineTotalGross: number
}

/** Part-type cart line item */
export interface PartCartLineItem extends BaseCartLineItem {
  lineType: 'part'
  partId: string
  barcode: string
  name: string
}

/** Labor-type cart line item */
export interface LaborCartLineItem extends BaseCartLineItem {
  lineType: 'labor'
  laborServiceId: string | null
  minutesWorked: number
  hourlyRateSnapshot: number // cents per hour, snapshot at add time
}

/** Bicycle-type cart line item */
export interface BicycleCartLineItem extends BaseCartLineItem {
  lineType: 'bicycle'
  bicycleId: string | null
  bicycleBrand: string | null
  bicycleModel: string | null
  bicycleYear: number | null
  bicycleColor: string | null
  bicycleFrameSize: string | null
}

/** A single line item in the cart — discriminated union of part/labor/bicycle */
export type CartLineItem = PartCartLineItem | LaborCartLineItem | BicycleCartLineItem

// ---------------------------------------------------------------------------
// Input types for adding labor/bicycle items to cart
// ---------------------------------------------------------------------------

/** Input for creating a labor line item in the cart */
export interface AddLaborInput {
  /** Human-readable description of the service */
  description: string
  /** Minutes worked (positive integer) */
  minutesWorked: number
  /** Hourly rate snapshot in cents per hour */
  hourlyRateSnapshot: number
  /** Optional reference to a predefined labor service */
  laborServiceId?: string | null
}

/** Input for creating a bicycle line item in the cart */
export interface AddBicycleInput {
  /** Human-readable description of the bicycle sale */
  description: string
  /** Unit price net (ex-tax cents) */
  priceNet: number
  /** Optional reference to a bicycle template */
  bicycleId?: string | null
  /** Bicycle brand name */
  bicycleBrand?: string | null
  /** Bicycle model name */
  bicycleModel?: string | null
  /** Model year */
  bicycleYear?: number | null
  /** Color */
  bicycleColor?: string | null
  /** Frame size (e.g. "56cm", "L") */
  bicycleFrameSize?: string | null
}

// ---------------------------------------------------------------------------
// Customer & Checkout Types
// ---------------------------------------------------------------------------

/** Customer selector item from GET /customers (search response) */
export interface CustomerSelectorItem {
  id: string
  displayName: string
  type: 'private' | 'company'
  email?: string | null
  phone?: string | null
}

/** Payload sent to POST /sales for checkout — matches server discriminated union schema */
export interface CheckoutPayload {
  customerId: string | null
  paymentMethod: 'cash' | 'card'
  lineItems: Array<
    | {
        lineType: 'part'
        partId: string
        description: string
        quantity: number
        unitPriceNet: number
        vatRateId: string
        discountPercent?: number | null
      }
    | {
        lineType: 'labor'
        laborServiceId?: string | null
        minutesWorked?: number | null
        hourlyRateSnapshot?: number | null
        description: string
        quantity: number
        unitPriceNet: number
        vatRateId: string
        discountPercent?: number | null
      }
    | {
        lineType: 'bicycle'
        bicycleId?: string | null
        bicycleBrand?: string | null
        bicycleModel?: string | null
        bicycleYear?: number | null
        bicycleColor?: string | null
        bicycleFrameSize?: string | null
        description: string
        quantity: number
        unitPriceNet: number
        vatRateId: string
        discountPercent?: number | null
      }
  >
}

/** Success info returned from POST /sales */
export interface CheckoutSuccess {
  saleNumber: string
  totalGross: number
}

// ============================================================================
// Helpers — Line item math (all amounts in cents, integer)
// ============================================================================

/**
 * Compute line totals from quantity, unit price, discount, and VAT rate.
 *
 * Formula: discountedNetPerUnit = unitPriceNet × (1 - discountBps / 10000)
 *          lineNetTotal = discountedNetPerUnit × quantity
 *          lineVatTotal = round(lineNetTotal × vatRateBps / 10000)
 *          lineGrossTotal = lineNetTotal + lineVatTotal
 */
function computeLineTotals(
  priceNet: number,
  quantity: number,
  discountPercentBps: number | null,
  vatRateBps: number
): { net: number; vat: number; gross: number } {
  const discountFactor = discountPercentBps ? 1 - discountPercentBps / 10000 : 1
  const discountedNetPerUnit = Math.round(priceNet * discountFactor)
  const lineNetTotal = discountedNetPerUnit * quantity
  const lineVatTotal = Math.round(lineNetTotal * vatRateBps / 10000)

  return { net: lineNetTotal, vat: lineVatTotal, gross: lineNetTotal + lineVatTotal }
}

/** Generate a unique ID for cart line items */
function generateLineItemId(): string {
  return `cart-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`
}

// ============================================================================
// Store
// ============================================================================

interface PosCartState {
  // Line items in the cart (discriminated union: part | labor | bicycle)
  lineItems: CartLineItem[]

  // Selected customer (null = walk-in)
  customerId: string | null

  // Checkout state
  checkoutError: string | null
  checkoutSuccess: CheckoutSuccess | null
  isCheckingOut: boolean

  // Computed totals (derived from line items)
  subtotalNet: number
  vatTotal: number
  totalGross: number

  // Whether the cart can be checked out
  canCheckout: boolean
}

interface PosCartActions {
  // Part line item operations (backward compatible with existing API)
  addLineItem: (part: PartCatalogItem, quantity?: number) => void

  // Labor line item operations
  addLaborLineItem: (input: AddLaborInput) => void

  // Bicycle line item operations
  addBicycleLineItem: (input: AddBicycleInput) => void

  // Generic line item operations (works for all types via unique id)
  removeLineItem: (id: string) => void
  updateQuantity: (id: string, quantity: number) => void
  applyDiscount: (id: string, discountPercentBps: number) => void
  changeVatRate: (id: string, newVatRateId: keyof typeof VAT_RATES) => void

  // Customer selection
  setCustomer: (customerId: string | null) => void

  // Checkout state management
  clearCart: () => void
  clearErrors: () => void
  startCheckout: () => void
  finishCheckout: (success: CheckoutSuccess) => void
  failCheckout: (error: string) => void
  setCheckoutError: (error: string | null) => void
  setCheckoutSuccess: (success: CheckoutSuccess | null) => void

  // Get checkout payload for API call
  getCheckoutPayload: () => CheckoutPayload
}

export type PosCartStore = PosCartState & PosCartActions

const initialState: PosCartState = {
  lineItems: [],
  customerId: null,
  checkoutError: null,
  checkoutSuccess: null,
  isCheckingOut: false,
  subtotalNet: 0,
  vatTotal: 0,
  totalGross: 0,
  canCheckout: false,
}

function computeTotals(lineItems: CartLineItem[]): { subtotalNet: number; vatTotal: number; totalGross: number } {
  let subtotalNet = 0
  let vatTotal = 0

  for (const item of lineItems) {
    const vatRateBps = VAT_RATES[item.vatRateId] ?? 2100
    const totals = computeLineTotals(item.priceNet, item.quantity, item.discountPercent, vatRateBps)
    subtotalNet += totals.net
    vatTotal += totals.vat
  }

  return { subtotalNet, vatTotal, totalGross: subtotalNet + vatTotal }
}

/** Compute line-level totals for a single cart item */
function computeItemTotals(item: Pick<BaseCartLineItem, 'priceNet' | 'quantity' | 'discountPercent' | 'vatRateId'>): {
  lineTotalNet: number
  lineTotalVat: number
  lineTotalGross: number
} {
  const vatRateBps = VAT_RATES[item.vatRateId] ?? 2100
  const { net, vat, gross } = computeLineTotals(item.priceNet, item.quantity, item.discountPercent, vatRateBps)
  return { lineTotalNet: net, lineTotalVat: vat, lineTotalGross: gross }
}

function updateComputedState(state: PosCartStore): Partial<PosCartState> {
  const totals = computeTotals(state.lineItems)
  return {
    ...totals,
    canCheckout: state.lineItems.length > 0,
  }
}

export const useCartStore = create<PosCartStore>((set, get) => ({
  ...initialState,

  // ── Part Line Item Operations (backward compatible) ─────────────

  addLineItem: (part, quantity = 1) => {
    set((state) => {
      // If quantity is 0 or less, remove existing line item(s) for this part
      if (quantity <= 0) {
        const newItems = state.lineItems.filter(
          (item) => item.lineType !== 'part' || item.partId !== part.id
        )
        return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
      }

      // Find existing part-type item with same partId
      const existingIndex = state.lineItems.findIndex(
        (item) => item.lineType === 'part' && (item as PartCartLineItem).partId === part.id
      )

      let newItems: CartLineItem[]

      if (existingIndex >= 0) {
        // Increment quantity for existing line item
        const existingItem = state.lineItems[existingIndex] as PartCartLineItem
        const newQty = existingItem.quantity + quantity
        newItems = [...state.lineItems]
        newItems[existingIndex] = {
          ...existingItem,
          quantity: newQty,
          ...computeItemTotals({ priceNet: existingItem.priceNet, quantity: newQty, discountPercent: existingItem.discountPercent, vatRateId: existingItem.vatRateId }),
        } as PartCartLineItem
      } else {
        // Add new part line item
        const totals = computeItemTotals({ priceNet: part.priceNet, quantity, discountPercent: null, vatRateId: DEFAULT_VAT_RATE })
        const newItem: PartCartLineItem = {
          id: generateLineItemId(),
          lineType: 'part',
          partId: part.id,
          barcode: part.barcode,
          name: part.name,
          description: part.name,
          priceNet: part.priceNet,
          quantity,
          vatRateId: DEFAULT_VAT_RATE,
          discountPercent: null,
          ...totals,
        }
        newItems = [...state.lineItems, newItem]
      }

      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  // ── Labor Line Item Operations ───────────────────────────────────

  addLaborLineItem: (input) => {
    set((state) => {
      // Compute priceNet from minutes and hourly rate: (minutesWorked / 60) * hourlyRateSnapshot
      const priceNet = Math.round((input.minutesWorked / 60) * input.hourlyRateSnapshot)

      const totals = computeItemTotals({ priceNet, quantity: 1, discountPercent: null, vatRateId: DEFAULT_VAT_RATE })
      const newItem: LaborCartLineItem = {
        id: generateLineItemId(),
        lineType: 'labor',
        description: input.description,
        laborServiceId: input.laborServiceId ?? null,
        minutesWorked: input.minutesWorked,
        hourlyRateSnapshot: input.hourlyRateSnapshot,
        priceNet,
        quantity: 1,
        vatRateId: DEFAULT_VAT_RATE,
        discountPercent: null,
        ...totals,
      }

      const newItems = [...state.lineItems, newItem]
      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  // ── Bicycle Line Item Operations ─────────────────────────────────

  addBicycleLineItem: (input) => {
    set((state) => {
      const totals = computeItemTotals({ priceNet: input.priceNet, quantity: 1, discountPercent: null, vatRateId: DEFAULT_VAT_RATE })
      const newItem: BicycleCartLineItem = {
        id: generateLineItemId(),
        lineType: 'bicycle',
        description: input.description,
        bicycleId: input.bicycleId ?? null,
        bicycleBrand: input.bicycleBrand ?? null,
        bicycleModel: input.bicycleModel ?? null,
        bicycleYear: input.bicycleYear ?? null,
        bicycleColor: input.bicycleColor ?? null,
        bicycleFrameSize: input.bicycleFrameSize ?? null,
        priceNet: input.priceNet,
        quantity: 1,
        vatRateId: DEFAULT_VAT_RATE,
        discountPercent: null,
        ...totals,
      }

      const newItems = [...state.lineItems, newItem]
      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  // ── Generic Line Item Operations (all types) ─────────────────────

  removeLineItem: (id) => {
    set((state) => {
      const newItems = state.lineItems.filter((item) => item.id !== id)
      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  updateQuantity: (id, quantity) => {
    set((state) => {
      // Remove if quantity is exactly 0
      if (quantity === 0) {
        const newItems = state.lineItems.filter((item) => item.id !== id)
        return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
      }

      // Clamp to minimum of 1 (negative values become 1)
      const clampedQty = Math.max(1, quantity)

      const newItems = state.lineItems.map((item) => {
        if (item.id !== id) return item
        return { ...item, quantity: clampedQty, ...computeItemTotals({ ...item, quantity: clampedQty }) } as CartLineItem
      })

      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  applyDiscount: (id, discountPercentBps) => {
    set((state) => {
      const newItems = state.lineItems.map((item) => {
        if (item.id !== id) return item
        return { ...item, discountPercent: discountPercentBps, ...computeItemTotals({ ...item, discountPercent: discountPercentBps }) } as CartLineItem
      })
      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  changeVatRate: (id, newVatRateId) => {
    set((state) => {
      const newItems = state.lineItems.map((item) => {
        if (item.id !== id) return item
        return { ...item, vatRateId: newVatRateId, ...computeItemTotals({ ...item, vatRateId: newVatRateId }) } as CartLineItem
      })
      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  // ── Customer Selection ──────────────────────────────────────────

  setCustomer: (customerId) => {
    set({ customerId })
  },

  // ── Checkout State Management ───────────────────────────────────

  clearCart: () => {
    set({ ...initialState, lineItems: [], customerId: null })
  },

  clearErrors: () => {
    set({ checkoutError: null, checkoutSuccess: null })
  },

  startCheckout: () => {
    set({ isCheckingOut: true, checkoutError: null })
  },

  failCheckout: (error) => {
    set({ isCheckingOut: false, checkoutError: error })
  },

  setCheckoutError: (error) => {
    set({ checkoutError: error })
  },

  setCheckoutSuccess: (success) => {
    set({ checkoutSuccess: success })
  },

  finishCheckout: (success) => {
    set({
      isCheckingOut: false,
      checkoutSuccess: success,
      lineItems: [],
      customerId: null,
      subtotalNet: 0,
      vatTotal: 0,
      totalGross: 0,
      canCheckout: false,
    })
  },

  // ── Checkout Payload Builder (discriminated union) ──────────────

  getCheckoutPayload: (): CheckoutPayload => {
    const state = get()
    return {
      customerId: state.customerId,
      paymentMethod: 'cash', // default — can be overridden by caller
      lineItems: state.lineItems.map((item) => {
        if (item.lineType === 'part') {
          const partItem = item as PartCartLineItem
          return {
            lineType: 'part' as const,
            partId: partItem.partId,
            description: partItem.description,
            quantity: partItem.quantity,
            unitPriceNet: partItem.priceNet,
            vatRateId: partItem.vatRateId,
            discountPercent: partItem.discountPercent,
          }
        }
        if (item.lineType === 'labor') {
          const laborItem = item as LaborCartLineItem
          return {
            lineType: 'labor' as const,
            description: laborItem.description,
            quantity: laborItem.quantity,
            unitPriceNet: laborItem.priceNet,
            vatRateId: laborItem.vatRateId,
            discountPercent: laborItem.discountPercent,
            laborServiceId: laborItem.laborServiceId ?? undefined,
            minutesWorked: laborItem.minutesWorked ?? undefined,
            hourlyRateSnapshot: laborItem.hourlyRateSnapshot ?? undefined,
          }
        }
        // bicycle
        const bicycleItem = item as BicycleCartLineItem
        return {
          lineType: 'bicycle' as const,
          description: bicycleItem.description,
          quantity: bicycleItem.quantity,
          unitPriceNet: bicycleItem.priceNet,
          vatRateId: bicycleItem.vatRateId,
          discountPercent: bicycleItem.discountPercent,
          bicycleId: bicycleItem.bicycleId ?? undefined,
          bicycleBrand: bicycleItem.bicycleBrand ?? undefined,
          bicycleModel: bicycleItem.bicycleModel ?? undefined,
          bicycleYear: bicycleItem.bicycleYear ?? undefined,
          bicycleColor: bicycleItem.bicycleColor ?? undefined,
          bicycleFrameSize: bicycleItem.bicycleFrameSize ?? undefined,
        }
      }),
    }
  },
}))

