it('computes correct totals with discount (in basis points)', () => {
  useCartStore.getState().addLineItem(mockPart, 2) // priceNet=500, qty=2 → gross net = 1000
  // Apply 10% discount = 1000 bps: discounted per unit = 500 × (1 - 1000/10000) = 450
