/**
 * POS feature types — explicit interfaces using shared domain types.
 *
 * This module defines all types used by the POS feature, importing from
 * `shared/types/` as the single source of truth for domain entities.
 */

import type { Product } from '@shared/types/product.js'
import type { Customer } from '@shared/types/customer.js'

// ============================================================================
// Shared Type Aliases — derived from shared types
// ============================================================================

/** Compact catalog item for list/table display and cart operations. */
export interface PartCatalogItem extends Pick<Product, 'id' | 'barcode' | 'name' | 'priceNet' | 'quantityOnHand'> {}

/** Customer selector item for dropdown selectors (compact shape). */
export interface CustomerSelectorItem extends Pick<Customer, 'id' | 'type'> {
  /** Human-readable name: "firstName lastName" for private, companyName for company. */
  displayName: string
}

// ============================================================================
// Cart Types — internal to the POS feature
// ============================================================================

/** VAT rate ID constants — matches server vatRates table. */
export const VAT_RATES = {
  'vat-standard': 2100, // 21%
  'vat-reduced': 600,   // 6%
  'vat-zero': 0,        // 0%
} as const

/** Default VAT rate for parts. */
export const DEFAULT_VAT_RATE = 'vat-standard' as const

// ---------------------------------------------------------------------------
// Cart Line Item — Discriminated Union (part | labor | bicycle)
// ---------------------------------------------------------------------------

/** Shared fields for all cart line item types */
interface BaseCartLineItem {
  /** Unique identifier for this line item in the cart */
  id: string
  /** Human-readable description of the line item */
  description: string
  /** Unit price net (ex-tax cents per unit, snapshot at add time) */
  priceNet: number
  /** Quantity of units */
  quantity: number
  /** VAT rate ID for this line item */
  vatRateId: keyof typeof VAT_RATES
  /** Discount in basis points, e.g. 1000 = 10% — null means no discount */
  discountPercent: number | null
  // Computed totals (updated whenever qty/discount changes)
  lineTotalNet: number
  lineTotalVat: number
  lineTotalGross: number
}

/** Part-type cart line item */
export interface PartCartLineItem extends BaseCartLineItem {
  lineType: 'part'
  partId: string
  barcode: string
  name: string
}

/** Labor-type cart line item */
export interface LaborCartLineItem extends BaseCartLineItem {
  lineType: 'labor'
  laborServiceId: string | null
  minutesWorked: number
  hourlyRateSnapshot: number // cents per hour, snapshot at add time
}

/** Bicycle-type cart line item */
export interface BicycleCartLineItem extends BaseCartLineItem {
  lineType: 'bicycle'
  bicycleId: string | null
  bicycleBrand: string | null
  bicycleModel: string | null
  bicycleYear: number | null
  bicycleColor: string | null
  bicycleFrameSize: string | null
}

/** A single line item in the cart — discriminated union of part/labor/bicycle */
export type CartLineItem = PartCartLineItem | LaborCartLineItem | BicycleCartLineItem

// ============================================================================
// Checkout Types — request/response shapes for the checkout flow
// ============================================================================

/** Payload sent to POST /sales for checkout — matches server discriminated union schema. */
export interface CheckoutPayload {
  customerId: string | null
  paymentMethod: 'cash' | 'card'
  lineItems: Array<
    | {
        lineType: 'part'
        partId: string
        description: string
        quantity: number
        unitPriceNet: number
        vatRateId: string
        discountPercent?: number | null
      }
    | {
        lineType: 'labor'
        laborServiceId?: string | null
        minutesWorked?: number | null
        hourlyRateSnapshot?: number | null
        description: string
        quantity: number
        unitPriceNet: number
        vatRateId: string
        discountPercent?: number | null
      }
    | {
        lineType: 'bicycle'
        bicycleId?: string | null
        bicycleBrand?: string | null
        bicycleModel?: string | null
        bicycleYear?: number | null
        bicycleColor?: string | null
        bicycleFrameSize?: string | null
        description: string
        quantity: number
        unitPriceNet: number
        vatRateId: string
        discountPercent?: number | null
      }
  >
}

/** Success info returned from POST /sales. */
export interface CheckoutSuccess {
  saleNumber: string
  totalGross: number
}

